import React, { useEffect, useState } from "react";
import "../css/style.css";
import { Link } from "react-router-dom";

const Header = () => {
  const [userEmail, setUserEmail] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [emailInput, setEmailInput] = useState("");
  const [passwordInput, setPasswordInput] = useState("");
  const [emailError, setEmailError] = useState("");

  useEffect(() => {
    const savedUser = JSON.parse(localStorage.getItem("user"));
    if (savedUser?.email) {
      setUserEmail(savedUser.email);
    }
  }, []);

  const validateEmail = (email) => {
    const re = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i;;
    return re.test(email);
  };

  const handleLogin = () => {
    if (!validateEmail(emailInput)) {
      setEmailError("Введіть коректний email.");
      return;
    }
  
    if (passwordInput.length === 0) {
      setEmailError("Введіть пароль.");
      return;
    }
  
    localStorage.setItem("user", JSON.stringify({ email: emailInput }));
    setUserEmail(emailInput);
    setShowModal(false);
    setEmailInput("");
    setPasswordInput("");
    setEmailError("");
    window.location.reload();
  };
  
  const handleLogout = () => {
    localStorage.removeItem("user");
    setUserEmail(null);
    window.location.reload();
  };

  return (
    <header className="header" id="header">
      <nav className="nav container">
        <Link to="/" className="nav__logo">
          <img src={process.env.PUBLIC_URL + "/images/Logo.png"} alt="Logo" />ЖивиТут
        </Link>

        <div className="nav__menu">
          <ul className="nav__list">
            <li className="nav__item">
              <Link to="/" className="nav__link">
                <i className="bx bx-home-alt-2"></i>
                <span>Головна</span>
              </Link>
            </li>
            <li className="nav__item">
              <Link to="/available" className="nav__link">
                <i className="bx bx-building-house"></i>
                <span>Доступні квартири</span>
              </Link>
            </li>
            <li className="nav__item">
              <Link to="/booked" className="nav__link">
                <i className="bx bx-bookmark"></i>
                <span>Мої бронювання</span>
              </Link>
            </li>
            <li className="nav__item">
              <Link to="/" className="nav__link">
                <i className="bx bx-phone"></i>
                <span>Контакти</span>
              </Link>
            </li>
          </ul>
        </div>

        {!userEmail ? (
          <button className="button nav__button" onClick={() => setShowModal(true)}>
            Увійти
          </button>
        ) : (
          <button className="button nav__button" onClick={handleLogout}>
            Вийти
          </button>
        )}
      </nav>

      {showModal && (
        <div className="modal">
          <div className="modal-content">
            <h2 className="model-header">Вхід</h2>
            <input
              type="email"
              placeholder="Email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
            />
            <input
              type="password"
              placeholder="Пароль"
              value={passwordInput}
              onChange={(e) => setPasswordInput(e.target.value)}
            />
            {emailError && <p className="error-text">{emailError}</p>}
            <div className="modal-buttons">
              <button onClick={handleLogin} className="button">Увійти</button>
              <button onClick={() => {
                setShowModal(false);
                setEmailError("");
              }} className="button button--gray">Скасувати</button>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;
