import React, { useEffect, useState } from "react";
import "../css/style.css";
import Footer from "../components/Footer";
import Header from "../components/Header";
import BookedList from "../components/BookedList";

const Flats = () => {
  const [bookings, setBookings] = useState([]);
  const [userEmail, setUserEmail] = useState("");
  const [flats, setFlats] = useState([]);

  useEffect(() => {
    const savedUser = JSON.parse(localStorage.getItem("user"));
    if (savedUser?.email) {
      setUserEmail(savedUser.email);
    }
  }, []);

  useEffect(() => {
    const storedBookings = JSON.parse(localStorage.getItem("bookings")) || [];
    setBookings(storedBookings);

    fetch(process.env.PUBLIC_URL + "/json/apartments.json")
      .then(res => res.json())
      .then(data => setFlats(data))
      .catch(err => console.error("Помилка завантаження квартир:", err));
  }, []);

  const cancelBooking = (indexToDelete) => {
    const updatedBookings = bookings.filter((_, index) => index !== indexToDelete);
    setBookings(updatedBookings);
    localStorage.setItem("bookings", JSON.stringify(updatedBookings));
  };

  return (
    <main className="main">
      <section className="booked section" id="booked">
        <div className="booked__container container">
          <div className="booked__info">
            <h1 className="user__email">Користувач: {userEmail || "Гість"}</h1>
            <h2 className="booked__title">Мої бронювання</h2>
          </div>
          <BookedList
            bookings={bookings}
            flats={flats}
            cancelBooking={cancelBooking}
          />
        </div>
      </section>
    </main>
  );
};

function Booked() {
  return (
    <div className="app">
      <Header />
      <Flats />
      <Footer />
    </div>
  );
}

export default Booked;
