import React from "react";
import "../css/style.css";
import Footer from "../components/Footer";
import Header from "../components/Header";
import Popular from "../components/Popular";

const Info = () => {
  return (
    <section className="home section" id="home">
      <div className="home__container container grid">
        <div className="home__data">
          <h1 className="home__title">Сучасна квартира для кожного</h1>
          <p className="home__description">
            Компанія «ЖивиТут» пропонує повний комплекс послуг з оренди квартир у Львові. Ми працюємо на ринку нерухомості вже понад 15 років.
          </p>
        </div>
        <div className="home__image">
          <img src="images/Home Image.png" alt="Home" />
        </div>
      </div>
    </section>
  );
};

const Contact = () => {
  return (
        <section className="contact section" id="contact">
            <div className="contact__container container">
                <div className="contact__images">
                    <div className="contact__orbe">
                        <div className="contact__img">
                            <img src="images/team.png"></img>
                        </div>
                    </div>    
                    <div className="contact__content">
                        <div className="contact__data">
                            <span className="section__subtitle">Зв'язок з нами</span>
                            <h2 className="section__title">
                                Завжди на зв'язку
                            </h2>
                            <p className="contact__description">
                                Маєте труднощі з пошуком дому мрії? Потрібна допомога у придбанні першого житла чи консультація з житлових питань? Просто зв’яжіться з нами
                            </p>
                        </div>
                        <div className="contact__card">
                            <div className="contact__card-box">
                                <div className="contact__card-info">
                                    <i className='bx bxs-phone' ></i>
                                    <div>
                                        <h3 className="contact__card-title">
                                            Телефон
                                        </h3>
                                        <p className="contact__card-description">
                                            +380935392376
                                        </p>
                                    </div>
                                </div>

                                <button className="button contact__card-button">
                                    Замовити виклик
                                </button>
                            </div>
                            
                            <div className="contact__card-box">
                                <div className="contact__card-info">
                                    <i className='bx bxl-telegram' ></i>
                                    <div>
                                        <h3 className="contact__card-title">
                                            Telegram
                                        </h3>
                                        <p className="contact__card-description">
                                            @ZhyvyTyt
                                        </p>
                                    </div>
                                </div>

                                <button className="button contact__card-button">
                                    Написати
                                </button>
                            </div>

                            <div className="contact__card-box">
                                <div className="contact__card-info">
                                    <i className='bx bxl-whatsapp-square' ></i>
                                    <div>
                                        <h3 className="contact__card-title">
                                            WhatsApp
                                        </h3>
                                        <p className="contact__card-description">
                                            +380935392376
                                        </p>
                                    </div>
                                </div>

                                <button className="button contact__card-button">
                                    Написати
                                </button>
                            </div>

                            <div className="contact__card-box">
                                <div className="contact__card-info">
                                    <i className='bx bxl-instagram' ></i>
                                    <div>
                                        <h3 className="contact__card-title">
                                            Instagram
                                        </h3>
                                        <p className="contact__card-description">
                                            @ZhyvyTytLviv
                                        </p>
                                    </div>
                                </div>

                                <button className="button contact__card-button">
                                    Переглянути квартири
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
  );
};

function Home() {
  return (
    <>
      <Header />
      <main className="main">
        <Info />
        <Popular />
        <Contact />
      </main>
      <Footer />
    </>
  );
}

export default Home;
