import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

const Popular = () => {
  const [flats, setFlats] = useState([]);

  useEffect(() => {
    fetch(process.env.PUBLIC_URL + "/json/apartments.json")
      .then((response) => response.json())
      .then((data) => setFlats(data.slice(0, 4)))
      .catch((error) => console.error("Помилка завантаження JSON:", error));
  }, []);

  return (
    <section className="popular section" id="popular">
      <div className="container">
        <h2 className="section__title">Популярні</h2>
        <span className="section__subtitle">
          Втілюйте свої кар’єрні мрії, насолоджуйтесь усіма можливостями центру міста та розкішним житлом сповна
        </span>
        <div className="popular__container">
          {flats.length > 0 ? (
            flats.map((flat) => (
              <Link to={`/apartment/${flat.id}`} className="found__link">
                <article className="popular__card">
                  <img src={flat.images[0]} alt="flat" className="popular__img" />
                  <div className="popular__data">
                    <h2 className="popular__price">
                      <span>{flat.price} грн/доба</span>
                    </h2>
                    <h3 className="popular__title">Площа: {flat.size} m<sup>2</sup></h3>
                    <h3 className="popular__description">{flat.location}</h3>
                  </div>
                </article>
              </Link>
            ))
          ) : (
            <p>Завантаження квартир...</p>
          )}
        </div>
      </div>
    </section>
  );
};

export default Popular;
