import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import DatePicker from "react-datepicker";
import { registerLocale } from "react-datepicker";
import uk from "date-fns/locale/uk";
import "react-datepicker/dist/react-datepicker.css";
import "../css/style.css";

registerLocale("uk", uk);

const FlatCard = ({ flat }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [bookedDates, setBookedDates] = useState([]);
  const [totalPrice, setTotalPrice] = useState(0);

  useEffect(() => {
    const existingBookings = JSON.parse(localStorage.getItem("bookings") || "[]");
    const currentFlatBookings = existingBookings
      .filter(b => b.flatId === flat.id)
      .map(b => ({ start: new Date(b.start), end: new Date(b.end) }));

    setBookedDates(currentFlatBookings);
  }, [flat.id]);
  
  const handleBooking = () => {
    if (startDate && endDate) {
      const isOverlapping = bookedDates.some(({ start, end }) => (
        startDate <= end && endDate >= start
      ));
  
      if (isOverlapping) {
        alert("Обрані дати перетинаються з уже існуючим бронюванням.");
        return;
      }
  
      const days = Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24));
      const newBooking = { start: startDate, end: endDate };
  
      const existing = JSON.parse(localStorage.getItem("bookings") || "[]");
      localStorage.setItem(
        "bookings",
        JSON.stringify([...existing, { flatId: flat.id, ...newBooking }])
      );
  
      setBookedDates(prev => [...prev, newBooking]);
      setTotalPrice(days * flat.price);
  
      alert("Бронювання успішне!");
      setIsModalOpen(false);
      setStartDate(null);
      setEndDate(null);
    }
  };

  const getExcludedDates = () => {
    return bookedDates.flatMap(({ start, end }) => {
      const dates = [];
      let current = new Date(start);
      while (current <= end) {
        dates.push(new Date(current));
        current.setDate(current.getDate() + 1);
      }
      return dates;
    });
  };

  return (
    <div className="found__card">
      <Link to={`/apartment/${flat.id}`} className="found__link">
        <img src={flat.images[0]} className="found__img" alt="Apartment" />
        <div className="found__data">
          <h2 className="found__title"><i className='bx bx-map'></i>{flat.location}</h2>
          <h2 className="found__rooms"><i className='bx bx-building'></i>{flat.rooms} кімнати</h2>
          <h2 className="found__type"><i className='bx bx-home-alt-2'></i>{flat.type}</h2>
          <h2 className="found__price"><i className='bx bx-purchase-tag'></i>{flat.price} грн/доба</h2>
        </div>
      </Link>
      <button className="button found__button" onClick={() => setIsModalOpen(true)}>Забронювати</button>
      {isModalOpen && (
        <div className="modal">
          <div className="modal-content">
            <h3>Оберіть дати бронювання</h3>
            <DatePicker
              locale="uk"
              selected={startDate}
              onChange={([start, end]) => {
                setStartDate(start);
                setEndDate(end);
              }}
              startDate={startDate}
              endDate={endDate}
              selectsRange
              excludeDates={getExcludedDates()}
              minDate={new Date()}
              placeholderText="Оберіть діапазон дат"
              dateFormat="dd.MM.yyyy"
              isClearable
            />
            {startDate && endDate ? (
              <p>Вартість: {Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24)) * flat.price} грн</p>
            ) : (
              <p>Не обрано дат</p>
            )}
            <div className="modal__actions">
              <button
                className="modal-button button"
                onClick={handleBooking}
                disabled={!startDate || !endDate || startDate.getTime() === endDate.getTime()}
              >
                Підтвердити
              </button>
              <button className="modal-button button" onClick={() => setIsModalOpen(false)}>
                Скасувати
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FlatCard;
