import React from "react";
import "../css/style.css";
import { Link } from "react-router-dom";

const Footer = () => {
  return (
    <footer className="footer section">
      <div className="footer__container container grid">
        <div className="footer__head">
          <Link to={"/"} className="footer__logo">
            <img src={process.env.PUBLIC_URL + "/images/Logo.png"} alt="Логотип" />ЖивиТут
          </Link>
          <p className="footer__description">Житло для кожного</p>
        </div>

        <div className="footer__content">
          <div>
            <h3 className="footer__title">Про нас</h3>
            <ul className="footer__links">
              <li><Link to={"/info"} className="footer__link">Вакансії</Link></li>
              <li><Link to={"/info"} className="footer__link">FAQ</Link></li>
              <li><Link to={"/info"} className="footer__link">Новини</Link></li>
            </ul>
          </div>

          <div>
            <h3 className="footer__title">Покупцям</h3>
            <ul className="footer__links">
              <li><Link to={"/info"} className="footer__link">Оплата</Link></li>
              <li><Link to={"/info"} className="footer__link">Партнери</Link></li>
              <li><Link to={"/info"} className="footer__link">Контакти</Link></li>
            </ul>
          </div>

          <div>
            <h3 className="footer__title">Співпраця</h3>
            <ul className="footer__links">
              <li><Link to={"/info"} className="footer__link">Рієлторам</Link></li>
              <li><Link to={"/info"} className="footer__link">Власникам</Link></li>
              <li><Link to={"/info"} className="footer__link">Розробникам</Link></li>
            </ul>
          </div>

          <div>
            <h3 className="footer__title">Контакти</h3>
            <ul className="footer__socials">
              <a href="https://www.facebook.com/" className="footer__social-link"><i className='bx bxl-facebook-circle'></i></a>
              <a href="https://www.pinterest.com/" className="footer__social-link"><i className='bx bxl-pinterest'></i></a>
              <a href="https://www.youtube.com/" className="footer__social-link"><i className='bx bxl-youtube'></i></a>
            </ul>
          </div>
        </div>
      </div>

      <div className="footer__info container">
        <span className="footer__copy">&#169; 2025 ЖивиТут. Всі права захищені</span>
        <div className="footer__privacy">
          <a href="/info#policy">Політика конфіденційності</a>
          <a href="/info#terms">Умови використання</a>
        </div>
      </div>
    </footer>
  );
};

export default Footer;