import React from "react";
import { Link } from "react-router-dom";

const BookedList = ({ bookings, flats, cancelBooking }) => {
  const getFlatById = (id) => flats.find(flat => flat.id === id);

  const formatDate = (dateStr) => {
    const d = new Date(dateStr);
    return d.toLocaleDateString("uk-UA", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
    });
  };

  return (
    <div className="booked__apartments">
      {bookings.length === 0 ? (
        <p>Немає активних бронювань.</p>
      ) : (
        bookings.map((booking, index) => {
          const flat = getFlatById(booking.flatId);
          if (!flat) return null;

          return (
            <div key={index} className="booked__card">
              <Link to={`/apartment/${flat.id}`} className="booked__link">
                <div className="booked__info">
                  <img src={flat.images[0]} className="booked__img" alt="Квартира" />
                  <h3 className="booked__street">{flat.location}</h3>
                  <p className="booked__dates">
                    {formatDate(booking.start)} — {formatDate(booking.end)}
                  </p>
                </div>
              </Link>
              <button
                className="button booked__cancel"
                onClick={() => cancelBooking(index)}
              >
                Відмінити
              </button>
            </div>
          );
        })
      )}
    </div>
  );
};

export default BookedList;
